final class Tarjeta {
    let nombre: String
    init(_ n: String) { nombre = n; print("nace \(n)") }
    deinit { print("muere \(nombre)") }
}
func demo() {
    let a = Tarjeta("A")
    var b: Tarjeta? = a
    print("a y b apuntan a \(b!.nombre)")
    b = nil
    print("b soltó; A sigue viva porque a la usa")
}
demo()
print("fin de demo: A ya murió")

